 "A title is up to {max} characters.": "Le titre fait {max} caractères maximum.",
 "A translation goes live as soon as it is done. Anything not translated yet shows in your default language.": "Une traduction est en ligne dès qu'elle est prête. Ce qui n'est pas encore traduit s'affiche dans ta langue par défaut.",
 "A video here is at most {maxVideo}": "Une vidéo ici fait au maximum {maxVideo}",
 "A video, playing on a loop": "Une vidéo en boucle",
