 "An empty React project.": "Un projet React vide.",
 "An empty repository works best. If the branch is protected on GitHub, type a new one, such as storelib, and Storelib makes it.": "Un dépôt vide fonctionne le mieux. Si la branche est protégée sur GitHub, saisissez-en une nouvelle, comme storelib, et Storelib la crée.",
 "An error occurred": "Une erreur s'est produite",
 "An error occurred while saving. Please try again.": "Une erreur est survenue lors de l'enregistrement. Réessayez.",
 "An error occurred. Please try again.": "Une erreur est survenue. Réessayez.",
 "An hour after a buyer leaves checkout without paying, if they asked for news. Turn it on in Checkout.": "Une heure après qu'un acheteur quitte le paiement sans payer, s'il a demandé des nouvelles. Activez-le dans Paiement.",
 "An hour after someone presses Pay and no order comes of it. Only people who ticked “Email me news and offers” at checkout, or are on your list, get it, and it stops the moment they buy.": "Une heure après que quelqu'un a appuyé sur Payer sans qu'une commande en résulte. Seules les personnes qui ont coché « M'envoyer des nouvelles et des offres » au paiement, ou qui sont dans votre liste, la reçoivent, et elle s'arrête dès qu'elles achètent.",
 "An icon beside the title": "Une icône à côté du titre",
 "An image beside the title": "Une image à côté du titre",
 "An image or GIF": "Une image ou un GIF",
 "An integration connects Storelib to a service you already use: Google Analytics, a pixel for your ads, a shipping or print on demand company.": "Une intégration relie Storelib à un service que vous utilisez déjà : Google Analytics, un pixel publicitaire, un transporteur ou un service d'impression à la demande.",
 "An invite is already an approval, so this only applies to anyone who asks without one.": "Une invitation vaut déjà validation : ceci ne s'applique qu'aux personnes qui demandent sans invitation.",
 "An invite lasts 1 to 365 days.": "Une invitation dure de 1 à 365 jours.",
 "An invite link is the only way in.": "Un lien d'invitation est le seul moyen d'entrer.",
 "An order": "Une commande",
 "An order, a payout, a dispute, your website or something that isn't working. A real person at Storelib reads every one and replies here.": "Une commande, un virement, un litige, votre site web ou quelque chose qui ne marche pas. Une vraie personne chez Storelib lit chaque message et répond ici.",
 "An unticked “Email me with news and offers” box under the email. Only buyers who tick it get your campaigns.": "Une case non cochée « Recevoir les nouveautés et offres par e-mail » sous l'e-mail. Seuls les acheteurs qui la cochent reçoivent vos campagnes.",
