 "At checkout Storelib looks at where the buyer is and adds that region's rate. Buyers anywhere else pay no tax.": "Au paiement, Storelib regarde où se trouve l'acheteur et ajoute le taux de cette région. Ailleurs, aucune taxe n'est payée.",
