 "CJ API key": "Clé API CJ",
 "CJ SKU or product words": "SKU CJ ou mots du produit",
 "CJ has nothing for that. Try other words, or the SKU from the CJ product page.": "CJ n'a rien pour ça. Essayez d'autres mots, ou le SKU de la page produit CJ.",
 "CJ lists no variants for it.": "CJ ne liste aucune variante pour lui.",
 "CJ › My CJ › Authorization › API, the API key (it looks like CJ1234567@api@…). Exchanged with CJ for a token, then stored encrypted on Storelib's server.": "CJ › My CJ › Authorization › API, la clé API (elle ressemble à CJ1234567@api@…). Échangée avec CJ contre un jeton, puis stockée chiffrée sur le serveur Storelib.",
