 "Cancel order": "Annuler la commande",
 "Cancel order on the buyer's order page while the order is still Unfulfilled. It is cancelled and refunded in full at once, its stock goes back on sale and you get an email. An order already sent to a print partner or an app asks you first.": "Annuler la commande sur la page de commande de l'acheteur tant qu'elle n'est pas traitée. Elle est annulée et remboursée intégralement tout de suite, son stock est remis en vente et vous recevez un e-mail. Une commande déjà envoyée à un partenaire d'impression ou à une app vous est d'abord demandée.",
