 "Checklists": "Check-lists",
 "Checkout": "Paiement",
 "Checkout always charges your store's own currency and says so next to the total, so a converted price is shown as an estimate.": "Le paiement est toujours encaissé dans la devise de votre boutique et l'indique à côté du total : un prix converti est donc une estimation.",
 "Checkout canceled. Nothing changed.": "Paiement annulé. Rien n'a changé.",
 "Checkout charges the visitor's currency, the amounts they saw. A currency Storelib can't charge yet is shown for reference, and checkout says it charges yours.": "Le paiement se fait dans la devise du visiteur, aux montants qu'il a vus. Une devise que Storelib ne peut pas encore encaisser est affichée à titre indicatif, et le paiement indique qu'il se fait dans la vôtre.",
 "Checkout charges what your store's prices are in, and says so next to the total, so a converted price is always shown as an estimate.": "Le paiement débite dans la devise des prix de votre boutique et l'indique à côté du total : un prix converti est toujours présenté comme une estimation.",
 "Checkout for the product they left": "Le paiement du produit laissé",
 "Checkout has no way to get an order to the buyer, so nobody can buy.": "Le paiement n'a aucun moyen de livrer l'acheteur, donc personne ne peut acheter.",
 "Checkout is closed until payments are set up again, so buyers cannot pay you in the meantime.": "Le paiement est fermé jusqu'à la reconfiguration, les acheteurs ne peuvent donc pas vous payer entre-temps.",
 "Checkout is the page where a buyer types their details and pays. These settings decide what it asks for.": "Le paiement est la page où l'acheteur saisit ses informations et paie. Ces réglages décident de ce qui est demandé.",
