 "Checks are not running yet on your account, so a flow with a check sends nothing for now. Remove the check to send without it.": "Les vérifications ne tournent pas encore sur votre compte : un scénario avec une vérification n'envoie rien pour l'instant. Retirez-la pour envoyer sans.",
