 "Duplicate": "Dupliquer",
 "Duplicate settings": "Dupliquer les paramètres",
 "Duplicate {name}": "Dupliquer {name}",
 "Dusk": "Crépuscule",
 "Dynamic Favicon": "Favicon dynamique",
 "E-books": "E-books",
 "EN": "EN",
 "Each charge lands here with its invoice.": "Chaque prélèvement apparaît ici avec sa facture.",
 "Each email goes to each person once, however often they trigger it. Someone who unsubscribes gets nothing more.": "Chaque e-mail est envoyé une fois à chaque personne, quel que soit le nombre de déclenchements. Une personne désabonnée ne reçoit plus rien.",
 "Each item is priced by its own weight, then added up.": "Chaque article est facturé selon son poids, puis additionné.",
 "Each item pays the price of the step its weight reaches. Two 0.5 {unit} items at a 0 {unit2} step of $3 pay $6.": "Chaque article paie le prix du palier atteint par son poids. Deux articles de 0,5 {unit} sur un palier de 0 {unit2} à 3 $ paient 6 $.",
 "Each language gets its own address, like yourstore.com/fr.": "Chaque langue a sa propre adresse, comme yourstore.com/fr.",
 "Each link needs a label and an https:// address.": "Chaque lien doit avoir un libellé et une adresse https://.",
 "Each new order for this location is sent here": "Chaque nouvelle commande de cet emplacement est envoyée ici",
 "Each new order is sent to your own system as a signed request. Set the address in Integrations.": "Chaque nouvelle commande est envoyée à votre propre système sous forme de requête signée. Définissez l'adresse dans Intégrations.",
 "Each new order with items from here is emailed to this partner with the items and the address. You add their tracking number in Orders when they ship.": "Chaque nouvelle commande avec des articles d'ici est envoyée par e-mail à ce partenaire avec les articles et l'adresse. Vous ajoutez leur numéro de suivi dans Commandes à l'expédition.",
 "Each order is printed and shipped for you.": "Chaque commande est imprimée et expédiée pour vous.",
 "Each order starts it once. The same order never starts it twice.": "Chaque commande la déclenche une fois. La même commande ne la déclenche jamais deux fois.",
 "Each paid order for your CJ location is sent to CJ with the CJ variants you matched, its tracking comes back, and CJ's stock can keep yours in step.": "Chaque commande payée pour votre emplacement CJ est envoyée à CJ avec les variantes associées, le suivi revient, et le stock CJ peut tenir le vôtre à jour.",
 "Each paid order for your Gelato location is sent to Gelato with the product and print file you matched, printed near your buyer, and its tracking comes back.": "Chaque commande payée pour votre emplacement Gelato est envoyée à Gelato avec le produit et le fichier d'impression associés, imprimée près de l'acheteur, et le suivi revient.",
 "Each paid order for your Printful location is sent to your Printful store by SKU, and its tracking comes back to your buyer.": "Chaque commande payée pour votre emplacement Printful est envoyée à votre boutique Printful par SKU, et le suivi revient à l'acheteur.",
 "Each paid order for your Printify location is sent to your Printify shop by SKU, and its tracking comes back to your buyer.": "Chaque commande payée pour votre emplacement Printify est envoyée à votre boutique Printify par SKU, et le suivi revient à l'acheteur.",
 "Each paid order is emailed to the location's supplier with the items and the address. Add tracking when they reply.": "Chaque commande payée est envoyée par e-mail au fournisseur de l'emplacement avec les articles et l'adresse. Ajoutez le suivi à sa réponse.",
 "Each paid order is sent to your https address as JSON, signed with your secret (X-Storelib-Signature).": "Chaque commande payée est envoyée à votre adresse https en JSON, signée avec votre secret (X-Storelib-Signature).",
 "Each paid order you ship goes to ShipStation. Print the label there and the tracking comes back to your buyer.": "Chaque commande payée à expédier part dans ShipStation. Imprimez-y l'étiquette et le suivi revient à l'acheteur.",
 "Each policy is a page of your site, linked from its footer. They start as templates: replace anything in square brackets with your own terms before you publish.": "Chaque politique est une page de votre site, liée depuis le pied de page. Elles partent de modèles : remplacez tout ce qui est entre crochets par vos propres conditions avant de publier.",
 "Each product page shows its own": "Chaque page produit affiche le sien",
 "Each product's stock is counted per location. When an order comes in, it is assigned to the default location, and its stock goes down there.": "Le stock de chaque produit est compté par emplacement. Une commande est affectée à l'emplacement par défaut, et son stock y diminue.",
 "Each push arrives within seconds, as a draft. Publish when you like it.": "Chaque push arrive en quelques secondes, en brouillon. Publiez quand cela vous plaît.",
 "Each question needs an answer.": "Chaque question doit avoir une réponse.",
 "Each rule needs a title.": "Chaque règle doit avoir un titre.",
 "Each sale becomes available about {settleDays} days after it is paid. That wait is set by our payment partner for your country and protects against refunds and disputes.": "Chaque vente est disponible environ {settleDays} jours après son paiement. Ce délai est fixé par notre partenaire de paiement pour votre pays et protège contre les remboursements et litiges.",
 "Each sale becomes available after a short settlement wait set by our payment partner for your country.": "Chaque vente est disponible après un court délai de règlement fixé par notre partenaire de paiement pour votre pays.",
 "Each variant has its own quantity, in Variants below.": "Chaque variante a sa propre quantité, dans Variantes ci-dessous.",
 "Earlier": "Plus tôt",
