 "That did not go through. Nothing changed. Try again.": "Cela n'a pas abouti. Rien n'a changé. Réessayez.",
 "Deleting on {date}": "Suppression le {date}",
 "The community stays": "La communauté est conservée",
 "Memberships ended with refunds. It is deleted once every refund has gone through.": "Les abonnements ont pris fin avec remboursement. Elle sera supprimée une fois tous les remboursements effectués.",
 "Memberships stopped renewing and nobody new can join. Members can read it until then. {stopped} of {total} memberships stopped.": "Les abonnements ne se renouvellent plus et personne ne peut rejoindre. Les membres peuvent la lire d'ici là. {stopped} abonnements arrêtés sur {total}.",
 "Keep the community": "Conserver la communauté",
 "{n, plural, one {# membership has} other {# memberships have}} not gone through with Stripe yet. Storelib tries again every few minutes.": "{n, plural, one {# abonnement n'a} other {# abonnements n'ont}} pas encore été traités par Stripe. Storelib réessaie toutes les quelques minutes.",
 "Keep this community?": "Conserver cette communauté ?",
 "Memberships renew again as before and the community comes back the way it was. Members are told by email.": "Les abonnements se renouvellent à nouveau comme avant et la communauté revient telle qu'elle était. Les membres sont prévenus par e-mail.",
 "{n, plural, one {# member pays} other {# members pay}} for it. Their memberships are cancelled first, then it is deleted.": "{n, plural, one {# membre paie} other {# membres paient}} pour elle. Leurs abonnements sont d'abord annulés, puis elle est supprimée.",
 "It disappears for everyone. Orders and payments are kept.": "Elle disparaît pour tout le monde. Les commandes et paiements sont conservés.",
 "End memberships and delete": "Mettre fin aux abonnements et supprimer",
 "Cancel memberships and delete": "Annuler les abonnements et supprimer",
 "{n, plural, one {# member pays} other {# members pay}} for this community. Nobody new can join from the moment you confirm, and every member gets an email.": "{n, plural, one {# membre paie} other {# membres paient}} pour cette communauté. Dès votre confirmation, plus personne ne peut rejoindre, et chaque membre reçoit un e-mail.",
 "When memberships end": "Quand les abonnements prennent fin",
 "When their paid time runs out": "À la fin de la période payée",
 "Renewals stop now and nobody is charged again. Members keep access until {date}, then the community is deleted. You can undo this until then.": "Les renouvellements s'arrêtent maintenant et personne n'est plus facturé. Les membres gardent l'accès jusqu'au {date}, puis la communauté est supprimée. Vous pouvez annuler d'ici là.",
 "Now, with refunds": "Maintenant, avec remboursement",
 "Memberships end today. Each member gets back what they paid for the time left, about {amount} in all. This cannot be undone.": "Les abonnements prennent fin aujourd'hui. Chaque membre est remboursé du temps restant, environ {amount} au total. Impossible d'annuler.",
 "Deleting a community members pay for is not switched on yet. Archive it for now; nobody can join an archived community.": "La suppression d'une communauté payante n'est pas encore activée. Archivez-la pour l'instant : personne ne peut rejoindre une communauté archivée.",
