 "Improved loading skeleton structures for Explore, Analytics, and Upgrade pages to better match actual page layouts.": "Les squelettes de chargement d'Explorer, Statistiques et Offres ressemblent davantage aux vraies pages.",
 "Improved settings page with smoother sticky save bar animations, toast notifications, and faster tab navigation with skeleton loading.": "Paramètres avec une barre d'enregistrement plus fluide, des notifications et un changement d'onglet plus rapide avec chargement progressif.",
 "Improvement": "Amélioration",
 "In 17TRACK, Settings > Webhook: add this address. 17TRACK signs updates with your API key. Without it Storelib checks every few hours.": "Dans 17TRACK, Settings > Webhook : ajoutez cette adresse. 17TRACK signe les mises à jour avec votre clé API. Sinon, Storelib vérifie toutes les quelques heures.",
