 "It comes off your page. If it has sales it is archived instead, so buyers keep their access.": "Il quitte votre page. S'il a des ventes, il est archivé pour que les acheteurs gardent leur accès.",
 "It could not be published. Try again.": "Impossible de publier. Réessayez.",
 "It disappears for everyone. Orders and payments are kept. Not possible while members still pay for it.": "Elle disparaît pour tout le monde. Les commandes et paiements sont conservés. Impossible tant que des membres paient.",
 "It goes back to their card in 5 to 10 business days, and your share comes back from your Stripe balance. They get an email.": "Le montant revient sur sa carte sous 5 à 10 jours ouvrés, et votre part est reprise sur votre solde Stripe. Il reçoit un e-mail.",
 "It goes live at": "Il sera en ligne sur",
 "It goes live at {site}.": "Il sera en ligne sur {site}.",
 "It happened {when}, across {count, plural, one {# sale} other {# sales}}.": "C'est arrivé {when}, sur {count, plural, one {# vente} other {# ventes}}.",
 "It has not been saved yet, so it will not be kept.": "Il n'a pas encore été enregistré, il ne sera donc pas conservé.",
 "It has not been saved yet, so nothing you added will be kept.": "Il n'a pas encore été enregistré, rien de ce que vous avez ajouté ne sera conservé.",
 "It has sales, so it will be archived, not deleted. It comes off your page and buyers keep their access.": "Il a des ventes : il sera archivé, pas supprimé. Il quitte votre page et les acheteurs gardent leur accès.",
 "It has to end after it starts.": "Il doit se terminer après son début.",
 "It hasn't arrived": "Il n'est pas arrivé",
 "It hides before it shows, so it would never be on the page.": "Il se masque avant de s'afficher : il ne serait jamais sur la page.",
 "It is a draft. Only you can see it until you publish.": "C'est un brouillon. Vous seul la voyez avant publication.",
 "It is gone for good, with its photos. To take it off your store and keep it, hide it instead.": "Il disparaît définitivement, avec ses photos. Pour le retirer de votre boutique en le gardant, masquez-le plutôt.",
 "It is hidden from your product page and its rating now. Storelib reads it and either brings it back or keeps it hidden.": "Il est désormais masqué sur votre page produit et dans sa note. Storelib le lit puis le rétablit ou le garde masqué.",
 "It is not a Storelib product and is not listed anywhere else.": "Ce n'est pas un produit Storelib et il n'est listé nulle part ailleurs.",
 "It is not connected yet, so nothing stops working.": "Il n'est pas encore connecté, donc rien ne cesse de fonctionner.",
 "It is off until you turn it on.": "Elle reste désactivée jusqu'à ce que vous l'activiez.",
 "It is removed from Messages. The email you got about it stays in your inbox, and the sender stays in your contacts.": "Il est retiré des Messages. L'e-mail reçu à ce sujet reste dans votre boîte, et l'expéditeur dans vos contacts.",
 "It is removed with its numbers. Anything already sent stays in people's inboxes.": "Elle est supprimée avec ses statistiques. Ce qui a déjà été envoyé reste dans les boîtes de réception.",
 "It is yours": "Il est à vous",
 "It may have been deleted. Go back to your websites.": "Il a peut-être été supprimé. Revenez à vos sites.",
 "It opens soon": "Ouverture prochaine",
 "It plays on your page in the YouTube or Vimeo player.": "Il est lu sur votre page dans le lecteur YouTube ou Vimeo.",
 "It reads Payment pending until you press Mark as paid on the order, once you have the cash. A parcel the buyer refuses: press Refused on delivery. Nothing is refunded, and what was sent comes back as a return.": "Elle indique Paiement en attente jusqu'à ce que vous appuyiez sur Marquer comme payée dans la commande, une fois l'argent reçu. Un colis refusé par l'acheteur : appuyez sur Refusée à la livraison. Rien n'est remboursé et ce qui a été envoyé revient en retour.",
 "It replaces “{name}” at": "Il remplace « {name} » sur",
 "It replaces “{name}” at {site}. Nothing is deleted.": "Il remplace « {name} » sur {site}. Rien n'est supprimé.",
 "It shows as cancelled to members, and anyone going hears about it. You can put it back on.": "Il apparaît comme annulé aux membres, et les participants sont prévenus. Vous pouvez le rétablir.",
 "It starts as a draft. Add its lessons, then publish it.": "Il démarre en brouillon. Ajoutez ses leçons, puis publiez-le.",
 "It stops at once for everyone partway through, and its history goes with it.": "Elle s'arrête aussitôt pour toutes les personnes en cours, et son historique disparaît avec elle.",
 "It takes nothing off downloads or courses in the same cart.": "Rien n'est déduit des téléchargements ou cours du même panier.",
 "It usually arrives in 1 to 3 business days.": "Il arrive généralement sous 1 à 3 jours ouvrés.",
 "It was already sent to your print partner. Cancel it there too.": "Elle a déjà été transmise à votre imprimeur. Annulez-la aussi là-bas.",
 "It was archived instead": "Il a été archivé à la place",
 "It was deleted. The email you got about it is still in your inbox.": "Il a été supprimé. L'e-mail reçu à ce sujet est toujours dans votre boîte.",
 "It was used, or it's past the return window.": "Il a été utilisé, ou le délai de retour est dépassé.",
 "It's a passport": "C'est un passeport",
 "It's here": "C'est arrivé",
 "It's kept as a draft, so the title and photos can wait. You come back to it here.": "Il est gardé en brouillon : le titre et les photos peuvent attendre. Vous le retrouvez ici.",
