 "Its photos, price, variants and how many you have.": "Ses photos, son prix, ses variantes et le stock.",
 "Its size and weight make shipping by weight and labels right.": "Sa taille et son poids rendent justes les tarifs au poids et les étiquettes.",
 "Its steps and history go with it.": "Ses étapes et son historique disparaissent avec elle.",
 "Its stock goes back on sale. The payment isn't refunded by this: use Refund on the order for that.": "Son stock repasse en vente. Le paiement n'est pas remboursé : utilisez Rembourser sur la commande pour cela.",
 "Its video and files go too, and buyers lose the lesson.": "Sa vidéo et ses fichiers disparaissent aussi, et les acheteurs perdent la leçon.",
