 "Members": "Membres",
 "Members are told about announcements.": "Les membres sont prévenus des annonces.",
 "Members can comment on posts here.": "Les membres peuvent commenter les publications ici.",
 "Members can read it; nobody can post. Bringing it back makes it a draft.": "Les membres peuvent la lire ; personne ne peut publier. La rétablir la repasse en brouillon.",
 "Members can see who else is here.": "Les membres peuvent voir qui d'autre est là.",
 "Members can still read it. Nobody can post or join until you bring it back. Nothing is deleted.": "Les membres peuvent toujours la lire. Personne ne peut publier ni rejoindre tant que vous ne la rétablissez pas. Rien n'est supprimé.",
 "Members earn points when their posts and comments get reactions, and climb levels. A leaderboard shows in the community.": "Les membres gagnent des points quand leurs publications et commentaires reçoivent des réactions, et montent de niveau. Un classement s'affiche dans la communauté.",
 "Members get these in their library while their membership lasts.": "Les membres les retrouvent dans leur bibliothèque tant que l'abonnement dure.",
 "Members now": "Membres actuels",
 "Members on {name}": "Membres de {name}",
 "Members pay for a tier to join.": "Les membres paient un niveau pour rejoindre.",
 "Members pay monthly or yearly to join your community.": "Les membres paient au mois ou à l'année pour rejoindre votre communauté.",
 "Members pay once, in a checkout inside the community. ": "Les membres paient une fois, via un paiement dans la communauté. ",
 "Members pay once, in a checkout inside the community. The meeting link, the address and who else is going open when they have a ticket.": "Les membres paient une fois, via un paiement dans la communauté. Le lien de réunion, l'adresse et la liste des participants s'affichent une fois le billet en main.",
 "Members pay through Stripe. You can add a yearly price or more tiers later.": "Les membres paient via Stripe. Vous pourrez ajouter un prix annuel ou d'autres niveaux plus tard.",
 "Members pay to join, every month, every year or once.": "Les membres paient pour rejoindre, chaque mois, chaque année ou une fois.",
 "Members pay you through Stripe. Nobody can join a paid community until payouts are connected.": "Les membres vous paient via Stripe. Personne ne peut rejoindre une communauté payante tant que les virements ne sont pas connectés.",
 "Members pay {amount} once, in a checkout inside the community. ": "Les membres paient {amount} une fois, via un paiement dans la communauté. ",
 "Members pay {priceText}.": "Les membres paient {priceText}.",
 "Members paying now, including anyone whose card is being retried. Somebody who cancelled keeps access until their period ends and is not counted.": "Les membres qui paient actuellement, y compris ceux dont la carte est en nouvelle tentative. Ceux qui ont annulé gardent l'accès jusqu'à la fin de leur période et ne sont pas comptés.",
 "Members post": "Les membres publient",
 "Members reach levels by taking part. Below it, they see the program with the level it opens at.": "Les membres atteignent des niveaux en participant. En dessous, ils voient le programme avec son niveau d'ouverture.",
 "Members see it under Learn.": "Les membres le voient dans Apprendre.",
 "Members see posts on their membership page. Put the membership on sale in Settings to let people join.": "Les membres voient les publications sur leur page d'abonnement. Mettez l'abonnement en vente dans Paramètres pour que les gens puissent rejoindre.",
 "Members see them before they join and when they post.": "Les membres les voient avant de rejoindre et quand ils publient.",
 "Members stop seeing it here. The course and its buyers are not touched.": "Les membres ne le voient plus ici. Le cours et ses acheteurs ne sont pas affectés.",
 "Members stop seeing it in the classroom. The course and its buyers are not touched.": "Les membres ne le voient plus dans la classe. Le cours et ses acheteurs ne sont pas affectés.",
 "Members stop seeing it, and every open report about it is closed. You can restore it from the Feed.": "Les membres ne le voient plus, et tous les signalements ouverts à son sujet sont clos. Vous pouvez le restaurer depuis le Fil.",
 "Members stop seeing it. You can restore it from Removed.": "Les membres ne la voient plus. Vous pouvez la restaurer depuis Retirées.",
 "Members who could attend can watch it on the event page afterwards.": "Les membres qui pouvaient y assister peuvent la regarder ensuite sur la page de l'événement.",
 "Members who have it lose it.": "Les membres qui l'ont le perdent.",
 "Members write to you from the community. Messages reach your inbox and this email; it stays private unless you show it.": "Les membres vous écrivent depuis la communauté. Les messages arrivent dans votre boîte et à cet e-mail ; il reste privé sauf si vous l'affichez.",
