 "October": "octobre",
 "Of the emails sent in this period, how many had a link clicked.": "Parmi les e-mails envoyés sur cette période, combien ont eu un lien cliqué.",
 "Of the emails sent in this period, how many were opened.": "Parmi les e-mails envoyés sur cette période, combien ont été ouverts.",
 "Of the emails your automations sent, how many were opened. Some mail apps hide opens, so this is a floor.": "Parmi les e-mails envoyés par vos automatisations, combien ont été ouverts. Certaines applications masquent les ouvertures : c'est un minimum.",
 "Of the people who visited, how many opened a product, how many started a checkout, and how many orders came in. Each step is shown as a share of the one before.": "Parmi les visiteurs, combien ont ouvert un produit, combien ont commencé un paiement et combien de commandes sont arrivées. Chaque étape est indiquée en part de la précédente.",
 "Off": "Désactivé",
 "Off each complete set.": "Sur chaque lot complet.",
 "Off every product in each complete set.": "Sur chaque produit de chaque lot complet.",
 "Off for things you hand over yourself.": "Désactivez pour ce que vous remettez vous-même.",
 "Off in your phone's settings. Turn this on to open {platform}.": "Désactivées dans les réglages du téléphone. Activez ceci pour ouvrir {platform}.",
 "Off keeps the market and sells to its countries as your home market.": "Désactivé, le marché est conservé et vend à ses pays comme votre marché principal.",
 "Off keeps this page out of Google and out of your sitemap.": "Désactivé, cette page reste hors de Google et de votre sitemap.",
 "Off one of it.": "Sur un exemplaire.",
 "Off sale": "Hors vente",
 "Off to keep stock here without shipping from it.": "Désactivez pour garder du stock ici sans expédier d'ici.",
 "Off to keep this location without shipping from it or offering pickup.": "Désactivez pour garder cet emplacement sans expédier ni proposer de retrait.",
 "Off topic": "Hors sujet",
 "Off, buyers pay your prices and nothing more.": "Désactivé, les acheteurs paient vos prix et rien de plus.",
 "Off, each order is made in CJ unpaid, and waits until you pay it there. On, it is confirmed and paid from your CJ balance as soon as your buyer pays.": "Désactivé, chaque commande est créée dans CJ impayée et attend votre paiement. Activé, elle est confirmée et payée depuis votre solde CJ dès que l'acheteur paie.",
 "Off, each order waits in {name} as a draft until you approve it there, and {name2} charges you only then. On, it is made and charged as soon as it is paid.": "Désactivé, chaque commande attend dans {name} en brouillon jusqu'à votre validation, et {name2} ne vous facture qu'à ce moment. Activé, elle est créée et facturée dès le paiement.",
 "Off, it follows your store setting: {value}{value2}.": "Désactivé, il suit le réglage de votre boutique : {value}{value2}.",
 "Off, it stays on your list and on your products, and isn't offered for new ones.": "Désactivé, il reste dans votre liste et sur vos produits, et n'est pas proposé pour les nouveaux.",
 "Off, its countries see your home market.": "Désactivé, ses pays voient votre marché principal.",
 "Off, the order page has no return button.": "Désactivé, la page de commande n'a pas de bouton de retour.",
 "Off. Sign-ups are still recorded.": "Désactivée. Les inscriptions restent enregistrées.",
 "Off. {stopped, plural, one {# person} other {# people}} stopped partway.": "Désactivée. {stopped, plural, one {# personne s'est arrêtée} other {# personnes se sont arrêtées}} en cours de route.",
 "Offer coaching sessions": "Proposez des séances de coaching",
 "Offer created": "Offre créée",
