 "Oldest": "Plus anciens",
 "Oldest first": "Les plus anciennes d'abord",
 "Omnisend › Store settings › API keys › Create API key, with the permissions listed below.": "Omnisend › Store settings › API keys › Create API key, avec les autorisations ci-dessous.",
 "Omnisend › Store settings › Connect store › your brand ID.": "Omnisend › Store settings › Connect store › votre ID de marque.",
 "On": "Activées",
 "On Free": "Sur Free",
 "On another computer, or lost the line?": "Sur un autre ordinateur, ou ligne perdue ?",
 "On any post or comment by a member ranked below them.": "Sur toute publication ou commentaire d'un membre de rang inférieur.",
 "On every page: your website, your storelib.com page and products, your OnePage, checkout and the thank you page, with product views, add to cart, checkout and purchases.": "Sur chaque page : votre site, votre page et vos produits storelib.com, votre OnePage, le paiement et la page de remerciement, avec les vues de produits, les ajouts au panier, les paiements et les achats.",
 "On hand": "En stock",
 "On hover": "Au survol",
 "On its way": "En route",
 "On its way back": "Sur le retour",
 "On order emails, so a buyer or a courier can reach you. It also helps your payment provider tell a real shop from a fraudulent one.": "Sur les e-mails de commande, pour qu'un acheteur ou un transporteur puisse vous joindre. Cela aide aussi votre prestataire de paiement à distinguer une vraie boutique d'une fraude.",
 "On receipts, order emails and checkout.": "Sur les reçus, e-mails de commande et la page de paiement.",
 "On receipts, order pages and every email your buyers get.": "Sur les reçus, les pages de commande et chaque e-mail reçu par vos acheteurs.",
 "On sale": "En vente",
