 "On the page:": "Sur la page :",
 "On the way": "En route",
 "On the way to your bank": "En route vers votre banque",
 "On their first visit, once the language is published. After that, what they pick.": "À leur première visite, une fois la langue publiée. Ensuite, ce qu'ils choisissent.",
 "On this website": "Sur ce site",
 "On your email list": "Sur votre liste e-mail",
 "On your website": "Sur votre site",
 "On {title}": "Sur {title}",
 "On. New people start it from now.": "Activée. Les nouvelles personnes la commencent dès maintenant.",
 "Onboarding reminders": "Rappels de démarrage",
 "Once it has passed, say": "Une fois passé, afficher",
 "Once it is available you can cash it out, and it usually reaches your bank in 1 to 3 business days.": "Une fois disponible, vous pouvez la retirer ; elle arrive généralement sur votre compte sous 1 à 3 jours ouvrés.",
 "Once it starts it cannot be taken back. You can stop the ones not yet sent.": "Une fois lancé, impossible de revenir en arrière. Vous pouvez arrêter ceux pas encore envoyés.",
 "Once per person": "Une fois par personne",
 "Once saved, they'll appear on your OnePage.": "Une fois enregistrées, elles apparaîtront sur votre OnePage.",
 "Once the items are back, mark them received: you choose whether they go back into stock, and you refund the buyer from the same screen.": "Une fois les articles revenus, marquez-les reçus : vous choisissez s'ils retournent en stock et remboursez l'acheteur depuis le même écran.",
 "One a line, for example\nfree followers\ncrypto signal*": "Un par ligne, par exemple\nabonnés gratuits\nsignal crypto*",
 "One email a day at most, listing what sold down to its low stock line.": "Un e-mail par jour au plus, listant ce qui est descendu à son seuil.",
 "One email an hour later with a link back to what they chose, only to buyers who ticked the news box. It stops the moment they buy.": "Un e-mail une heure plus tard avec un lien vers ce qu'il a choisi, uniquement aux acheteurs ayant coché la case newsletter. Il s'arrête dès qu'ils achètent.",
 "One email an hour later, only to buyers who ticked the news box. With the news box hidden nobody can tick it, so no reminder goes out.": "Un e-mail une heure plus tard, uniquement aux acheteurs ayant coché la case newsletter. Si la case est masquée, personne ne peut la cocher, donc aucun rappel n'est envoyé.",
 "One event has a price, and nobody can buy a ticket until payouts are connected.": "Un événement a un prix, et personne ne peut acheter de billet tant que les virements ne sont pas connectés.",
 "One event has a ticket price, but payouts are not connected, so nobody can buy it.": "Un événement a un prix, mais les virements ne sont pas connectés : personne ne peut acheter de billet.",
 "One every {value}": "Un toutes les {value}",
 "One fewer": "Un de moins",
