 "One image at a time": "Une image à la fois",
 "One kind of section: start the rule with": "Un seul type de section : commencez la règle par",
 "One kind of section: start the rule with {selector}. Your own coded sections keep their own styles unless you target them.": "Un type de section : commencez la règle par {selector}. Vos sections codées gardent leurs styles sauf si vous les ciblez.",
