 "Only approved translations show, and only once a language is published. Anything not translated yet shows in your default language, never blank.": "Seules les traductions approuvées s'affichent, et seulement une fois la langue publiée. Le reste s'affiche dans votre langue par défaut, jamais vide.",
 "Only buyers who asked for your news": "Seulement les acheteurs qui ont demandé vos nouvelles",
