 "Only on orders over": "Seulement pour les commandes de plus de",
 "Only on orders over an amount": "Uniquement sur les commandes au-dessus d'un montant",
 "Only one currency can be for all other countries.": "Une seule devise peut être pour tous les autres pays.",
 "Only orders delivered to these countries. Pickups can always pay in cash.": "Seulement les commandes livrées dans ces pays. Les retraits peuvent toujours être payés en espèces.",
 "Only orders placed after you turn the app on are asked. Buyers who turned review emails off, or already reviewed, are never asked.": "Seules les commandes passées après l'activation de l'appli sont concernées. Les acheteurs qui ont désactivé ces e-mails, ou ont déjà laissé un avis, ne sont jamais sollicités.",
 "Only people who asked for your news get it.": "Seules les personnes qui ont demandé vos nouvelles la reçoivent.",
 "Only people who trigger it after you turn it on are sent anything. Someone who unsubscribes is never sent another email, wherever they are in the flow.": "Seules les personnes qui la déclenchent après son activation reçoivent quelque chose. Une personne désabonnée ne reçoit plus aucun e-mail, où qu'elle en soit dans le flux.",
 "Only people you invite": "Uniquement les personnes invitées",
