 "Optional, like usps_priority (Shippo) or Priority (EasyPost). Empty: the cheapest.": "Facultatif, comme usps_priority (Shippo) ou Priority (EasyPost). Vide : le moins cher.",
 "Optional. A line under the name, for you.": "Facultatif. Une ligne sous le nom, pour vous.",
 "Optional. Drag to reorder images.": "Facultatif. Glissez pour réordonner les images.",
 "Optional. Each paid order for this product is emailed here with the items and address. Empty: you pass orders on yourself.": "Facultatif. Chaque commande payée de ce produit est envoyée ici par e-mail avec les articles et l'adresse. Vide : vous transmettez vous-même.",
 "Optional. Empty: always free.": "Facultatif. Vide : toujours gratuit.",
 "Optional. The code after # on the order.": "Facultatif. Le code après # sur la commande.",
 "Optional. Visitors from other countries see prices converted to their currency. Checkout always charges {currency}.": "Facultatif. Les visiteurs d'autres pays voient les prix convertis dans leur devise. Le paiement est toujours encaissé en {currency}.",
 "Optional. Visitors from other countries see your prices in their currency and pay in it.": "Facultatif. Les visiteurs d'autres pays voient vos prix dans leur devise et paient dans celle-ci.",
 "Optional. Visitors in the countries you list see prices in that currency and pay in it. Everyone else sees {currency}. Anyone can switch with your website's currency selector.": "Facultatif. Les visiteurs des pays que vous indiquez voient les prix dans cette devise et paient dans cette devise. Les autres voient {currency}. Chacun peut changer avec le sélecteur de devise de votre site.",
 "Optional. Visitors in these countries see your prices in their currency, can switch with your website's currency selector, and pay in it.": "Facultatif. Les visiteurs de ces pays voient vos prix dans leur devise, peuvent en changer avec le sélecteur de devise de votre site et paient dans cette devise.",
 "Optional. What it's for, for you and your team.": "Facultatif. À quoi il sert, pour vous et votre équipe.",
