 "Store details need their database update (SQL part 109). Until it runs, what you see here is not saved.": "Les infos de la boutique nécessitent leur mise à jour de base de données (partie SQL 109). En attendant, ce que vous voyez ici n'est pas enregistré.",
 "Store is unpublished. Go to Settings to publish.": "La boutique n'est pas publiée. Allez dans Paramètres pour la publier.",
