 "Store setup, {setupProgressPercent}% done": "Configuration de la boutique, {setupProgressPercent} % terminé",
 "Stored encrypted and never shown again.": "Stockée chiffrée et jamais réaffichée.",
 "Storelib AI": "Storelib AI",
 "Storelib AI could not be reached. Check your connection and try again.": "Impossible de joindre Storelib AI. Vérifiez votre connexion et réessayez.",
 "Storelib AI is already included in your plan. Connect your own Claude or OpenAI API key to use your account for that provider without counting those edits against your plan.": "Storelib AI est déjà inclus dans ton forfait. Connecte ta propre clé d'API Claude ou OpenAI pour utiliser ton compte chez ce fournisseur sans que ces modifications comptent dans ton forfait.",
 "Storelib AI is already included in your plan. If you would rather it ran on your own OpenAI key, connect it here and those edits stop counting against your plan's AI edits.": "Storelib AI est déjà inclus dans votre offre. Si vous préférez qu'il utilise votre propre clé OpenAI, connectez-la ici et ces modifications ne compteront plus dans les modifications IA de votre offre.",
 "Storelib AI is busy right now. Try again in a moment.": "Storelib AI est occupé. Réessayez dans un instant.",
 "Storelib AI isn't available right now. You can still translate each text yourself.": "Storelib AI n'est pas disponible pour le moment. Vous pouvez toujours traduire chaque texte vous-même.",
 "Storelib AI now answers on your account. Your key is used for your chats only, kept encrypted, and never shown again.": "Storelib AI répond désormais avec votre compte. Votre clé sert uniquement à vos chats, reste chiffrée et n'est jamais réaffichée.",
 "Storelib AI reads these before every change on every one of your websites. Tell it “remember this” in the builder, or add one here.": "Storelib AI lit ceci avant chaque modification sur tous vos sites. Dites-lui « retiens ceci » dans l'éditeur, ou ajoutez-le ici.",
 "Storelib Help Center": "Centre d'aide Storelib",
 "Storelib Payments": "Storelib Payments",
 "Storelib Reviews is on": "Storelib Reviews est activé",
 "Storelib Reviews needs its database update (SQL part 134). Until it runs, nothing here is kept.": "Storelib Reviews nécessite sa mise à jour de base de données (partie SQL 134). En attendant, rien n'est conservé ici.",
 "Storelib address": "Adresse Storelib",
 "Storelib adds the package's empty weight to the products inside when it works out a weight based shipping rate, so the buyer pays for what the parcel really weighs.": "Storelib ajoute le poids à vide du colis aux produits pour calculer un tarif au poids, afin que l'acheteur paie le poids réel du colis.",
 "Storelib apps": "Applis Storelib",
 "Storelib apps and the services you already use.": "Les applis Storelib et les services que vous utilisez déjà.",
 "Storelib badge hidden": "Badge Storelib masqué",
 "Storelib badge shown": "Badge Storelib affiché",
 "Storelib can't reach your repository": "Storelib ne peut pas accéder à votre dépôt",
 "Storelib can't take card payments in {local} yet, so your store sells in {currency}.": "Storelib ne peut pas encore encaisser les paiements par carte en {local}, votre boutique vend donc en {currency}.",
 "Storelib cannot see any repositories. Give it access to one on GitHub, then": "Storelib ne voit aucun dépôt. Donnez-lui accès à l'un d'eux sur GitHub, puis",
 "Storelib charges what you set and nothing more. Ask an accountant which rates apply to you.": "Storelib facture ce que vous définissez, rien de plus. Demandez à un comptable quels taux s'appliquent.",
 "Storelib charges what you set here and nothing more. Check which rates apply to you with an accountant.": "Storelib facture ce que vous définissez ici, rien de plus. Vérifiez les taux applicables avec un comptable.",
 "Storelib couldn't open your site to take the push": "Storelib n'a pas pu ouvrir votre site pour recevoir le push",
 "Storelib couldn't sign in to your repository. Reconnect GitHub and try again. Nothing on your site was lost.": "Storelib n'a pas pu se connecter à votre dépôt. Reconnectez GitHub et réessayez. Rien n'a été perdu sur votre site.",
 "Storelib didn't answer": "Storelib n'a pas répondu",
 "Storelib doesn't take changes to this file": "Storelib ne prend pas les modifications de ce fichier",
 "Storelib fee": "Frais Storelib",
 "Storelib includes it in the answer to the bank.": "Storelib l'ajoute à la réponse envoyée à la banque.",
 "Storelib is answering the bank. Add anything that proves the sale so it can be sent with the response.": "Storelib répond à la banque. Ajoutez tout ce qui prouve la vente pour l'envoyer avec la réponse.",
 "Storelib is helping with this case. Its messages go to you and the buyer.": "Storelib aide sur cette demande. Ses messages vous parviennent, à vous et à l'acheteur.",
 "Storelib is not allowed to use the microphone. Allow Microphone in Storelib's app permissions, then try again.": "Storelib n'a pas accès au micro. Autorisez le micro dans les autorisations de l'appli Storelib, puis réessayez.",
 "Storelib is not allowed to use the microphone. Turn on Microphone for Storelib in Settings, then try again.": "Storelib n'a pas accès au micro. Activez Micro pour Storelib dans Réglages, puis réessayez.",
 "Storelib news": "Actualités Storelib",
