 "Storelib profile": "Profil Storelib",
 "Storelib support": "Assistance Storelib",
 "Storelib suspended this community. Members cannot open it. Contact support to talk about it.": "Storelib a suspendu cette communauté. Les membres ne peuvent pas l'ouvrir. Contactez le support pour en parler.",
 "Storelib took this community out of Explore. Contact support to talk about it.": "Storelib a retiré cette communauté d'Explorer. Contactez le support pour en parler.",
 "Storelib was just updated. Refresh the page and try again.": "Storelib vient d'être mis à jour. Actualisez la page et réessayez.",
 "Storelib will look at the case and write to you both.": "Storelib examinera la demande et vous écrira à tous les deux.",
 "Storelib writes this website's whole theme into it: settings, pages, header and footer, sections and blocks, with an AGENTS.md your tool reads first.": "Storelib y écrit tout le thème de ce site : réglages, pages, en-tête et pied de page, sections et blocs, avec un AGENTS.md que votre outil lit en premier.",
 "Storelib's fee for your plan ({freeFee} on Free, {proFee} on Pro), and Stripe's card processing fee, which Stripe charges on every plan. There is nothing else.": "Les frais Storelib de votre offre ({freeFee} en Gratuit, {proFee} en Pro), et les frais de traitement de carte de Stripe, prélevés par Stripe sur toutes les offres. Rien d'autre.",
 "Storelib, automatically": "Storelib, automatiquement",
