 "Stripe checks your ID to confirm you are who you say you are. It goes straight to Stripe, and Storelib never sees or keeps the document.": "Stripe vérifie votre pièce d'identité pour confirmer que vous êtes bien vous. Elle part directement chez Stripe, et Storelib ne voit ni ne garde jamais le document.",
