 "The ID and bank forms only load on a real account. Everything around them is the real page.": "Les formulaires d'identité et bancaires ne se chargent que sur un vrai compte. Tout le reste est la vraie page.",
 "The Morning Writers": "Les Écrivains du Matin",
 "The Storelib app was removed from your GitHub account. Reconnect GitHub to keep syncing.": "L'appli Storelib a été retirée de votre compte GitHub. Reconnectez GitHub pour continuer la synchro.",
 "The account your payouts go to.": "Le compte qui reçoit vos virements.",
 "The activity log needs SQL part 113 (supabase/sql/run-now/113_store_activity.sql). Once it has run, changes show here from then on.": "Le journal d'activité nécessite la partie SQL 113 (supabase/sql/run-now/113_store_activity.sql). Une fois exécutée, les modifications s'affichent ici à partir de ce moment.",
 "The address of your Storelib page": "L'adresse de votre page Storelib",
 "The address of your creator page and your OnePage": "L'adresse de votre page créateur et de votre OnePage",
 "The answer": "La réponse",
 "The apron in Sage sold out.": "Le tablier Sauge est en rupture.",
 "The apron was worn, so we can't take it back.": "Le tablier a été porté, nous ne pouvons donc pas le reprendre.",
 "The bank decided for you. The money was returned to your balance.": "La banque a tranché en votre faveur. L'argent est revenu sur votre solde.",
 "The bio and small print": "La bio et les petits caractères",
 "The boxes and mailers you ship in. The default one's weight is added to the order for weight based rates.": "Les cartons et enveloppes que vous utilisez. Le poids du colis par défaut s'ajoute à la commande pour les tarifs au poids.",
 "The bread baking course": "Le cours de boulangerie",
 "The business could not be created. Try again.": "Impossible de créer l'entreprise. Réessayez.",
 "The buyer": "L'acheteur",
 "The buyer asked for it": "L'acheteur l'a demandé",
 "The buyer asked for the receipt again": "L'acheteur a redemandé le reçu",
 "The buyer bought my preset pack on Oct 3, got the download email and downloaded the files twice the same day.": "L'acheteur a acheté mon pack de presets le 3 oct., a reçu l'e-mail de téléchargement et a téléchargé les fichiers deux fois le jour même.",
 "The buyer can follow it at": "L'acheteur peut le suivre sur",
 "The buyer changed their email": "L'acheteur a changé son e-mail",
 "The buyer chooses Cash on delivery at checkout. The order is placed at once, with no card, and you send it as usual.": "L'acheteur choisit Paiement à la livraison au paiement. La commande est passée aussitôt, sans carte, et vous l'envoyez comme d'habitude.",
 "The buyer disputed this payment": "L'acheteur a contesté ce paiement",
 "The buyer does not recognise the payment on their statement.": "L'acheteur ne reconnaît pas le paiement sur son relevé.",
 "The buyer drops it off": "L'acheteur le dépose",
 "The buyer gets an email at each step: approved (with where to send it), received, and refunded.": "L'acheteur reçoit un e-mail à chaque étape : approuvé (avec l'adresse d'envoi), reçu et remboursé.",
 "The buyer gets the money back on their original payment method.": "L'acheteur est remboursé sur son moyen de paiement d'origine.",
 "The buyer paid at checkout.": "L'acheteur a payé au moment de la commande.",
 "The buyer says they did not get what they paid for.": "L'acheteur dit ne pas avoir reçu ce qu'il a payé.",
 "The buyer ships it back": "L'acheteur le renvoie",
 "The buyer's library": "La bibliothèque de l'acheteur",
 "The carrier couldn't be read last time: {error} Storelib tries again.": "Le transporteur n'a pas pu être lu la dernière fois : {error} Storelib réessaie.",
 "The carrier reported a problem delivering this package. The buyer sees it and gets the Delivery problem email. Contact them or the carrier, then mark it in transit or delivered when it moves.": "Le transporteur a signalé un problème de livraison pour ce colis. L'acheteur le voit et reçoit l'e-mail Problème de livraison. Contactez-le ou le transporteur, puis marquez-le en transit ou livré quand il bouge.",
 "The cart has certain products": "Le panier contient certains produits",
 "The channels a product starts on when you make it. You can change it on the product.": "Les canaux sur lesquels un produit démarre à sa création. Vous pouvez le modifier sur le produit.",
