 "The cover, then pictures and videos at the top of your page, the first one shown first.": "La couverture, puis les images et vidéos en haut de votre page, la première affichée en premier.",
 "The daily figures start after the first nightly count. Today’s numbers below are live.": "Les chiffres quotidiens commencent après le premier comptage nocturne. Les chiffres du jour ci-dessous sont en direct.",
 "The day after a purchase, where to find it and how to get help.": "Le lendemain d'un achat : où le trouver et comment obtenir de l'aide.",
 "The default tier": "Le niveau par défaut",
