 "The description is {size}, over the {limit} limit. Pictures saved inside the text by the old editor count toward it: remove them and add them again with the photo button.": "La description fait {size}, au-delà de la limite de {limit}. Les images enregistrées dans le texte par l'ancien éditeur comptent : retirez-les et ajoutez-les à nouveau avec le bouton photo.",
 "The description is {size}, over the {limit} limit. Shorten it, or remove formatting that came with a paste.": "La description fait {size}, au-delà de la limite de {limit}. Raccourcissez-la ou retirez la mise en forme venue d'un collage.",
 "The details on your payments account.": "Les informations de votre compte de paiement.",
