 "The edit failed.": "La modification a échoué.",
 "The editor is still loading your theme.": "L'éditeur charge encore votre thème.",
 "The editor opens in your default language and currency. Switch them with your theme's own language and currency selectors on the page, as visitors do.": "L'éditeur s'ouvre dans votre langue et votre devise par défaut. Changez-les avec les sélecteurs de langue et de devise de votre thème sur la page, comme les visiteurs.",
 "The editor, the preview and your website all open in your default language and your store currency. Switch them with your theme's own selectors on the page, as visitors do.": "L'éditeur, l'aperçu et votre site s'ouvrent dans votre langue par défaut et la devise de votre boutique. Changez-les avec les sélecteurs de votre thème sur la page, comme les visiteurs.",
 "The email": "L'e-mail",
 "The email and its numbers are removed from Storelib. What was sent stays in people's inboxes.": "L'e-mail et ses statistiques sont supprimés de Storelib. Ce qui a été envoyé reste dans les boîtes de réception.",
 "The email as your subscribers will get it, with your name filled in, to": "L'e-mail tel que vos abonnés le recevront, avec votre nom renseigné, à",
