 "The email didn't go out. Use Resend in a minute.": "L'e-mail n'est pas parti. Utilisez Renvoyer dans une minute.",
 "The email was not changed. Try again.": "L'e-mail n'a pas été modifié. Réessayez.",
 "The email was not deleted. Try again.": "L'e-mail n'a pas été supprimé. Réessayez.",
 "The email you sign in with. Use another one if buyers should write somewhere else.": "L'e-mail avec lequel vous vous connectez. Utilisez-en un autre si les acheteurs doivent écrire ailleurs.",
 "The emails your buyers get from your store: receipts, order and shipping updates, returns and the checkout reminder.": "Les e-mails que vos acheteurs reçoivent de votre boutique : reçus, suivi de commande et de livraison, retours et le rappel de paiement.",
 "The end has to be after the start.": "La fin doit être après le début.",
