 "The languages your website is offered in. Visitors pick theirs from the language selector, and each language has its own address, like /fr.": "Les langues dans lesquelles votre site est proposé. Les visiteurs choisissent la leur dans le sélecteur, et chaque langue a sa propre adresse, comme /fr.",
