 "The lessons show up here as soon as they are added.": "Les leçons apparaissent ici dès qu'elles sont ajoutées.",
 "The line shown after the subject in the inbox": "La ligne affichée après l'objet dans la boîte de réception",
 "The line under the title. One or two sentences about what you sell.": "La ligne sous le titre. Une ou deux phrases sur ce que vous vendez.",
 "The link could not be copied.": "Impossible de copier le lien.",
 "The link in their email stops working.": "Le lien de son e-mail ne fonctionne plus.",
 "The link sent to {email} stops working. You can invite them again later.": "Le lien envoyé à {email} ne fonctionne plus. Vous pourrez réinviter cette personne plus tard.",
 "The links and buttons on your OnePage that were tapped most, by the name they have on the page, and how many people tapped each.": "Les liens et boutons de votre OnePage les plus touchés, avec leur nom sur la page et le nombre de personnes qui ont touché chacun.",
