 "The money goes back to the buyer's original payment method, and they get an email about it.": "L'argent retourne sur le moyen de paiement d'origine de l'acheteur, qui reçoit un e-mail à ce sujet.",
 "The money is back in your available balance. Check your bank details, then cash out again.": "L'argent est revenu sur votre solde disponible. Vérifiez vos coordonnées bancaires puis retirez à nouveau.",
 "The most one buyer can take in one order": "Le maximum qu'un acheteur peut prendre par commande",
 "The new account is used for your next payout.": "Le nouveau compte sera utilisé pour votre prochain virement.",
 "The newest 30 are kept. A backup identical to the one before it is not saved twice.": "Les 30 plus récentes sont conservées. Une sauvegarde identique à la précédente n'est pas enregistrée deux fois.",
 "The newest exchange rates are from {asOf}, which is too old to use. Markets show your own prices until new rates arrive.": "Les taux de change les plus récents datent du {asOf}, trop anciens pour être utilisés. Les marchés affichent vos propres prix jusqu'à l'arrivée de nouveaux taux.",
 "The number sold, on the product page": "Le nombre vendu, sur la page produit",
