 "The order did not save.": "L'ordre n'a pas été enregistré.",
 "The order goes to {name} by each variant's SKU, and its tracking comes back to your buyer by itself.": "La commande part chez {name} selon le SKU de chaque variante, et le suivi revient automatiquement à l'acheteur.",
 "The order is still loading.": "La commande est encore en cours de chargement.",
