 "The order moves to the new address. Nothing is sent, as nothing in it has been paid for yet.": "La commande passe à la nouvelle adresse. Rien n'est envoyé, car rien n'a encore été payé.",
 "The order pays the price of the last step it reaches. The first step starts from 0. A $0 step is free shipping from there.": "La commande paie le prix du dernier palier atteint. Le premier palier commence à 0. Un palier à 0 $ offre la livraison à partir de là.",
 "The order pays the price of the last step its weight reaches, products plus your default package. The first step starts from 0.": "La commande paie le prix du dernier palier atteint par son poids, produits plus votre colis par défaut. Le premier palier commence à 0.",
 "The order was not saved.": "L'ordre n'a pas été enregistré.",
