 "To do": "À faire",
 "To keep your payouts going, Stripe asks for this now{value}. It takes a minute.": "Pour que vos virements continuent, Stripe le demande maintenant{value}. Cela prend une minute.",
 "To move a photo or video, press Space or Enter on it, then the arrow keys. Press Space or Enter again to drop it, or Escape to put it back. The first is the thumbnail.": "Pour déplacer une photo ou une vidéo, appuyez sur Espace ou Entrée dessus, puis sur les flèches. Appuyez à nouveau sur Espace ou Entrée pour la déposer, ou sur Échap pour l'annuler. La première est la vignette.",
 "To move a question, press Space or Enter on its handle, then the up and down arrow keys. Press Space or Enter again to drop it, or Escape to put it back.": "Pour déplacer une question, appuyez sur Espace ou Entrée sur sa poignée, puis sur les flèches haut et bas. Appuyez à nouveau sur Espace ou Entrée pour la déposer, ou sur Échap pour l'annuler.",
 "To move an option, press Space on its handle, then the up and down arrow keys, then Space again.": "Pour déplacer une option, appuyez sur Espace sur sa poignée, puis les flèches haut et bas, puis Espace à nouveau.",
