 "Two custom fields have the same name": "Deux champs personnalisés portent le même nom",
 "Two months after a purchase, and only if they have not bought since.": "Deux mois après un achat, et seulement s'ils n'ont pas racheté depuis.",
 "Two options have the same name": "Deux options ont le même nom",
 "Two or three clear ones are enough: be kind, stay on topic, no selling.": "Deux ou trois règles claires suffisent : soyez bienveillant, restez dans le sujet, pas de vente.",
 "Two variants have the same SKU": "Deux variantes ont le même SKU",
 "Type": "Type",
