 "Type an address or pick a page": "Saisissez une adresse ou choisissez une page",
 "Type both again to replace them.": "Saisissez les deux à nouveau pour les remplacer.",
 "Type the domain and press Connect. You get the records to add where you bought it, and the site answers there once they are in, usually within the hour.": "Saisissez le domaine et appuyez sur Connecter. Vous obtenez les enregistrements à ajouter chez votre registraire, et le site y répond dès qu'ils sont en place, généralement en moins d'une heure.",
 "Type the ticket price, like 25 or 25.50.": "Saisissez le prix du billet, comme 25 ou 25,50.",
