 "Visitors see your password page until they type the password.": "Les visiteurs voient votre page de mot de passe jusqu'à ce qu'ils le saisissent.",
 "Visitors start in": "Les visiteurs démarrent en",
 "Visitors switch with the language selector. On a Storelib theme it sits under the footer by itself. On a theme you imported from Shopify it is the theme's own selector, turned on in the editor (Show language, usually in the header or footer).": "Les visiteurs changent avec le sélecteur de langue. Sur un thème Storelib, il est seul sous le pied de page. Sur un thème importé de Shopify, c'est le sélecteur du thème, activé dans l'éditeur (Show language, généralement en en-tête ou pied de page).",
 "Visitors switch with your theme's language selector. Turn on Show visitors their own language to open a first visit in their browser's language.": "Les visiteurs changent avec le sélecteur de langue de votre thème. Activez Afficher aux visiteurs leur propre langue pour ouvrir une première visite dans la langue de leur navigateur.",
 "Voice input cannot hear this language here. Type it instead.": "La saisie vocale ne comprend pas cette langue ici. Tapez plutôt.",
 "Voice input needs a connection. Check it and try again.": "La saisie vocale nécessite une connexion. Vérifiez-la et réessayez.",
 "Voice input stopped before it heard anything. Try again, or type it.": "La saisie vocale s'est arrêtée avant d'entendre quoi que ce soit. Réessayez, ou tapez.",
 "Void label": "Annuler l'étiquette",
 "Void this {providerName} label? {cost} is refunded once the carrier agrees it wasn't used, and the items go back to unfulfilled.": "Annuler cette étiquette {providerName} ? {cost} sont remboursés une fois que le transporteur confirme qu'elle n'a pas servi, et les articles repassent en non traités.",
 "Voided": "Annulé",
