 "What you price in. Visitors anywhere not listed under More currencies see prices in it and pay in it.": "La devise de vos prix. Les visiteurs de tout pays hors de Autres devises voient les prix dans cette devise et paient dans cette devise.",
 "What you price in. Visitors in {country}, and anywhere not listed under More currencies, see prices in it and pay in it.": "La devise de vos prix. Les visiteurs en {country}, et partout ailleurs hors de Autres devises, voient les prix dans cette devise et paient dans cette devise.",
 "What you will cover and who it is for": "Ce que vous allez aborder et à qui ça s'adresse",
 "What you wrote in this email is replaced.": "Ce que vous avez écrit dans cet e-mail sera remplacé.",
 "What your buyers get from you, and when. Open one to see it and change its words. Each goes out with your store's name, and a reply comes to your contact email.": "Ce que vos acheteurs reçoivent de vous, et quand. Ouvrez-en un pour le voir et modifier son texte. Chacun part avec le nom de votre boutique, et les réponses arrivent à votre e-mail de contact.",
 "What your completed sales took in over this period, before fees and refunds.": "Ce que vos ventes finalisées ont rapporté sur cette période, avant frais et remboursements.",
 "What your website is written in now. It keeps its addresses as they are.": "La langue actuelle de votre site. Ses adresses restent inchangées.",
