 "WhatsApp Group URL": "URL du groupe WhatsApp",
 "Wheel throwing, from clay to cup": "Tournage, de l'argile à la tasse",
 "When": "Quand",
 "When a buyer asks to return items, so they know it arrived.": "Quand un acheteur demande un retour, pour qu'il sache que c'est arrivé.",
 "When a buyer has a problem with an order (it hasn't arrived, it came damaged, they want a refund), they ask from their order page and it lands here and in your email. You answer first; either of you can ask Storelib to step in.": "Quand un acheteur a un problème avec une commande (elle n'est pas arrivée, elle est abîmée, il veut un remboursement), il le signale depuis sa page de commande et la demande arrive ici et par e-mail. Vous répondez en premier ; chacun peut demander à Storelib d'intervenir.",
 "When a draft was last changed.": "Quand un brouillon a été modifié pour la dernière fois.",
 "When a review comes in": "Quand un avis arrive",
 "When a shipment is marked as failed: the carrier, or your own delivery, couldn't deliver it.": "Quand un envoi est marqué en échec : le transporteur, ou votre propre livraison, n'a pas pu livrer.",
 "When a store's owner invites you, it shows here and you can open it from your own account.": "Quand le propriétaire d'une boutique vous invite, elle apparaît ici et vous pouvez l'ouvrir depuis votre compte.",
 "When buyers can come. Shown at checkout and in the pickup email.": "Quand les acheteurs peuvent venir. Affiché au paiement et dans l'e-mail de retrait.",
 "When does Pro pay for itself?": "Quand Pro est-il rentabilisé ?",
 "When it pushes to": "Quand il pousse sur",
 "When it pushes to {branch}, the change shows here as a draft within seconds.": "Quand il pousse sur {branch}, la modification apparaît ici en brouillon en quelques secondes.",
 "When it's marked delivered.": "Quand il est marqué livré.",
 "When members leave they can say why. Their answers show up here.": "En partant, les membres peuvent dire pourquoi. Leurs réponses apparaissent ici.",
 "When members report a post, a comment or somebody, it lands here.": "Quand des membres signalent une publication, un commentaire ou une personne, cela arrive ici.",
 "When pressed": "À l'appui",
 "When returns are on, a buyer sees Request a return on their order page for as many days as your return window.": "Avec les retours activés, l'acheteur voit Demander un retour sur sa page de commande pendant votre délai de retour.",
 "When somebody writes to you through the contact form on your website, the message shows here and in your email.": "Quand quelqu'un vous écrit via le formulaire de contact de votre site, le message apparaît ici et dans votre boîte e-mail.",
 "When someone joins your list": "Quand quelqu'un rejoint votre liste",
