 "When the return is closed, with any refund.": "Quand le retour est clos, avec un éventuel remboursement.",
 "When visitors subscribe, they can download \"": "Quand les visiteurs s'abonnent, ils peuvent télécharger «",
 "When will my order arrive?": "Quand ma commande arrivera-t-elle ?",
 "When you add a product, ship an order or change a setting, it shows up here.": "Quand vous ajoutez un produit, expédiez une commande ou modifiez un paramètre, cela apparaît ici.",
 "When you approve a return, with your instructions.": "Quand vous approuvez un retour, avec vos instructions.",
