 "When you mark it collected.": "Quand vous le marquez retiré.",
 "When you mark items shipped, with the tracking.": "Quand vous marquez des articles expédiés, avec le suivi.",
 "When you publish changes, new and edited text is translated into your other languages within a few minutes. Translations you edit yourself are never replaced.": "Quand vous publiez des modifications, le texte nouveau ou modifié est traduit dans vos autres langues en quelques minutes. Les traductions que vous modifiez vous-même ne sont jamais remplacées.",
