 "Wins": "Victoires",
 "With Show visitors their own language on, a first visit opens in the published language the browser asks for, once. A close match, or only the country to go by, gets a small offer on the page instead. A market can also start its countries in its own language. After that the visitor's choice wins, and search engines still see every language at its own address.": "Avec « Montrer aux visiteurs leur langue » activé, une première visite s'ouvre une fois dans la langue publiée demandée par le navigateur. Une langue proche, ou seulement le pays, reçoit plutôt une petite proposition sur la page. Un marché peut aussi ouvrir ses pays dans sa propre langue. Ensuite, le choix du visiteur l'emporte, et les moteurs de recherche voient toujours chaque langue à sa propre adresse.",
