 "Your prices are in it and buyers pay in it. Payouts still arrive in your bank's currency.": "Vos prix sont dans cette devise et les acheteurs paient dans cette devise. Les virements arrivent toujours dans la devise de votre banque.",
 "Your prices are in {baseCurrency}. Cards are charged in {chargeCurrency}. A market in another currency shows an estimate converted at the European Central Bank's rate, and says so before payment.": "Vos prix sont en {baseCurrency}. Les cartes sont débitées en {chargeCurrency}. Un marché dans une autre devise affiche une estimation au taux de la Banque centrale européenne, et le précise avant le paiement.",
 "Your prices, your website, the builder and checkout all use it.": "Vos prix, votre site, l'éditeur et le paiement l'utilisent tous.",
 "Your product has no stock yet. Add some so buyers can order it.": "Votre produit n'a pas encore de stock. Ajoutez-en pour que les acheteurs puissent commander.",
 "Your products": "Vos produits",
 "Your products, pages, customers and orders stay as they are.": "Vos produits, pages, clients et commandes restent tels quels.",
 "Your products, pages, customers and orders stay exactly as they are. The Free fee applies to new sales, and the things only Pro has, like your own domain and hidden branding, stop at the end of your paid period.": "Vos produits, pages, clients et commandes restent tels quels. Les frais Gratuit s'appliquent aux nouvelles ventes, et ce qui est propre à Pro, comme votre domaine et la marque masquée, s'arrête à la fin de la période payée.",
 "Your profile photo, until you choose a logo.": "Votre photo de profil, jusqu'à ce que vous choisissiez un logo.",
 "Your programs and lessons, inside the community.": "Vos programmes et leçons, dans la communauté.",
 "Your questions": "Vos questions",
 "Your rates go by weight, so without one they ship at the lightest price.": "Vos tarifs dépendent du poids : sans poids, ils partent au tarif le plus léger.",
 "Your receipt for The bread baking course": "Votre reçu pour Le cours de boulangerie",
 "Your reply": "Votre réponse",
 "Your requests": "Vos demandes",
 "Your return window and a link to your refund policy, under Check out.": "Votre délai de retour et un lien vers votre politique de remboursement, sous Payer.",
 "Your return window and the reasons a buyer can choose.": "Votre délai de retour et les motifs que l'acheteur peut choisir.",
 "Your role can review reports but not remove content.": "Votre rôle peut examiner les signalements mais pas retirer de contenu.",
 "Your role in this community cannot do that.": "Votre rôle dans cette communauté ne le permet pas.",
 "Your sales show up here as soon as someone buys, with what they paid and what you keep.": "Vos ventes apparaissent ici dès qu'un achat est fait, avec ce qui a été payé et ce que vous gardez.",
 "Your session ended. Sign in again to use Storelib AI.": "Votre session a expiré. Reconnectez-vous pour utiliser Storelib AI.",
