 "Your store has the essentials": "Votre boutique a l'essentiel",
 "Your store is ready": "Votre boutique est prête",
 "Your store is set up": "Votre boutique est prête",
 "Your store logo.": "Le logo de votre boutique.",
 "Your store name": "Nom de votre boutique",
 "Your store opens in three steps": "Votre boutique ouvre en trois étapes",
 "Your store was not saved": "Votre boutique n'a pas été enregistrée",
 "Your store's contact email, from Settings › Store details. A buyer who answers an email writes to it.": "L'e-mail de contact de votre boutique, dans Paramètres › Infos de la boutique. Un acheteur qui répond à un e-mail vous écrit à cette adresse.",
 "Your store's country": "Le pays de votre boutique",
 "Your store's name and contact details go on receipts, order emails and your checkout, so buyers know who they bought from.": "Le nom et les coordonnées de votre boutique figurent sur les reçus, e-mails de commande et le paiement, pour que les acheteurs sachent à qui ils ont acheté.",
 "Your store, products, customers and details are removed. People who bought from you keep what they bought, and your sales and payout records are kept.": "Votre boutique, vos produits, clients et informations sont supprimés. Les acheteurs gardent ce qu'ils ont acheté, et vos historiques de ventes et de virements sont conservés.",
 "Your storelib.com addresses keep working. Once your website's domain is connected, its storelib.com address sends visitors there.": "Vos adresses storelib.com continuent de fonctionner. Une fois le domaine de votre site connecté, son adresse storelib.com y redirige les visiteurs.",
 "Your store’s name as it is when the email is sent": "Le nom de votre boutique au moment de l'envoi",
 "Your subscribers who said yes, and the orders of the last 90 days, in batches. Past orders are sent as history, so no automation emails them again.": "Vos abonnés qui ont dit oui et les commandes des 90 derniers jours, par lots. Les commandes passées sont envoyées comme historique, donc aucune automatisation ne les recontacte.",
 "Your subscription was canceled.": "Votre abonnement a été annulé.",
