 "Your website in more languages.": "Votre site dans plus de langues.",
 "Your website is at {liveHost}. Its other addresses send visitors there.": "Votre site est sur {liveHost}. Ses autres adresses y redirigent les visiteurs.",
 "Your website is offline": "Votre site web est hors ligne",
 "Your website stays at its own address in your default language. Every other language gets the same pages under its code: yourstore.com/fr, yourstore.com/fr/products/mug.": "Votre site reste à sa propre adresse dans votre langue par défaut. Chaque autre langue a les mêmes pages sous son code : votreboutique.com/fr, votreboutique.com/fr/products/mug.",
 "Your website's refund policy page ends with this, kept up to date for you. Website settings, Commerce can add it to the cart too.": "La page de politique de remboursement de votre site se termine par ceci, tenu à jour pour vous. Paramètres du site, Commerce peut aussi l'ajouter au panier.",
