 "You are the seller of your products, so registering for tax where you need to, and filing and paying it, stays with you. Storelib does not file or pay tax for you.": "Vous êtes le vendeur de vos produits : l'immatriculation fiscale là où elle est nécessaire, la déclaration et le paiement restent à votre charge. Storelib ne déclare ni ne paie de taxes pour vous.",
 "Community plans and memberships are paid through Storelib's Stripe account. When Storelib has Stripe Tax switched on, Stripe works out their rate from where the buyer is.": "Les formules de communauté et les abonnements sont payés via le compte Stripe de Storelib. Quand Storelib a activé Stripe Tax, Stripe calcule leur taux selon l'endroit où se trouve l'acheteur.",
 "Not sure what applies to you? An accountant can tell you in one conversation, and the CSV above is what they will ask for.": "Vous ne savez pas ce qui s'applique à vous ? Un comptable peut vous le dire en une conversation, et le CSV ci-dessus est ce qu'il vous demandera.",
